views {
  dynamic view login_journey {
    title "Login journey"

    user -> webApp "Open sign-in page"
    user -> webApp "Submit credentials"
    webApp -> api "POST /login"
    api -> primaryDatabase "Verify user and password"
    api -> notificationService "Send login event/notification"
    api -> webApp "Return session/token"
    webApp -> user "Show logged-in state"
  }
}

dynamic view auth_flow {
  webApp -> api_container.auth_component "Submit credentials"
  api_container.auth_component -> primaryDatabase "Load account and verify password"
  api_container.auth_component -> webApp "Return token/session"
}

views {
  dynamic view async_processing {
    title "Async flow: external user to processing worker"

    externalUser -> webApp "Start request"
    webApp -> api "Submit job"
    api -> jobQueue "Enqueue work"
    api -> webApp "202 Accepted + tracking id"
    webApp -> externalUser "Show accepted state"

    jobQueue -> processingWorker "Deliver queued job"
    processingWorker -> database "Persist result"
  }
}
